import {CREATURE_BY_ID,REGIONS,REGION_BY_ID} from './rpg-data.js';
export function createRpgStore(storage,onError=()=>{}){
 function sanitize(d){const s={caught:[],bond:{},buddy:null,visited:['willow'],xp:0,rulesVersion:2,legacyCleared:[]};if(!d||typeof d!=='object')return s;s.caught=[...new Set(Array.isArray(d.caught)?d.caught:[])].filter(id=>CREATURE_BY_ID[id]);s.buddy=s.caught.includes(d.buddy)?d.buddy:null;s.visited=[...new Set(['willow',...(Array.isArray(d.visited)?d.visited:[])])].filter(id=>REGION_BY_ID[id]);for(const id of s.caught)s.bond[id]=Number.isSafeInteger(d.bond?.[id])&&d.bond[id]>0&&d.bond[id]<=999?d.bond[id]:1;s.xp=Number.isSafeInteger(d.xp)&&d.xp>=0&&d.xp<1e9?d.xp:s.caught.length*40;s.legacyCleared=d.rulesVersion===2?(Array.isArray(d.legacyCleared)?d.legacyCleared:[]).filter(id=>REGIONS.some(r=>r.id===id)):REGIONS.filter(r=>s.caught.filter(id=>CREATURE_BY_ID[id].region===r.id).length>=3).map(r=>r.id);return s}
 let raw;try{raw=JSON.parse(storage.getItem('uspeak-rpg-v1'))}catch{}let s=sanitize(raw),rule=null,warned=false;
 const copy=()=>JSON.parse(JSON.stringify(s));
 function save(n){try{storage.setItem('uspeak-rpg-v1',JSON.stringify(n))}catch{if(!warned){warned=true;onError()}}s=n}
 const count=region=>s.caught.filter(id=>CREATURE_BY_ID[id].region===region).length;
 const cleared=region=>s.legacyCleared.includes(region)||(rule?rule(region):count(region)>=3);
 const unlocked=id=>{const r=REGION_BY_ID[id];return !!r&&(r.hub||r.needs.every(cleared))};
 return {get state(){return copy()},count,cleared,unlocked,setRules(fn){rule=fn;save(copy())},unlockedIds:()=>['willow','park','errand','school','arena','pet','ride','town',...REGIONS.filter(r=>unlocked(r.id)).map(r=>r.id)],capture(id){const c=CREATURE_BY_ID[id];if(!c||!unlocked(c.region))throw new Error('この地域はまだ解放されていません');const before=this.unlockedIds(),n=copy(),isNew=!n.caught.includes(id);if(isNew)n.caught.push(id);n.bond[id]=Math.min(999,(n.bond[id]||0)+1);n.xp+=isNew?40:10;if(!n.buddy)n.buddy=id;save(n);return {isNew,unlocked:this.unlockedIds().filter(id=>!before.includes(id))}},addXp(amount){if(!Number.isFinite(amount)||amount<0)return;const n=copy();n.xp=Math.min(999999999,n.xp+Math.floor(amount));save(n)},selectBuddy(id){if(!s.caught.includes(id))throw new Error('仲間にしたキャラクターを選んでください');const n=copy();n.buddy=id;save(n)},visit(id){if(!unlocked(id))throw new Error('まだ飛べない地域です');const n=copy();if(!n.visited.includes(id))n.visited.push(id);save(n)},restore(d){save(sanitize(d))}};
}
